namespace sv_e00df196fbfd4b648896e54637c463ea.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service holding the currently selected warehouse for one user circuit.
/// Fires OnChange when the selection changes so all subscribed components re-render.
/// </summary>
public class WarehouseState
{
    private string _selectedWarehouseId = "wh-1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A – East" },
        new() { Id = "wh-2", Name = "Warehouse B – West" },
        new() { Id = "wh-3", Name = "Warehouse C – Central" },
    ];

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_e00df196fbfd4b648896e54637c463ea.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit (user session) gets its own instance, ensuring independent state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background thread when new alert data arrives.
    /// Subscribers MUST wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds. Uses reference counting so multiple
    /// subscribers don't create multiple timers.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    /// <summary>
    /// Decrements the subscriber count. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
        }
    }

    /// <summary>
    /// Forces an immediate refresh (e.g., when warehouse selection changes).
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fetch immediately on start
        LowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertDataChanged?.Invoke();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                LowStockCount = await GetLowStockCountAsync(warehouseId);
                OnAlertDataChanged?.Invoke();
            }
        }
        catch (OperationCanceledException) { }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
    }
}

