@using sv_e00df196fbfd4b648896e54637c463ea.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm d-inline-block w-auto ms-2"
            @onchange="OnWarehouseChanged" value="@WarehouseState.SelectedWarehouseId">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChange;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "";
        WarehouseState.SetWarehouse(newId);
        // Refresh alerts for the new warehouse immediately
        await AlertService.RefreshAsync(newId);
    }

    private void HandleStateChange() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChange;
    }
}

@using sv_e00df196fbfd4b648896e54637c463ea.Services
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.LowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill ms-1">@AlertService.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill ms-1">0</span>
    }
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertDataChanged -= _handler;
        }
    }
}

