@page "/dashboard"
@using sv_e00df196fbfd4b648896e54637c463ea.Services
@using sv_e00df196fbfd4b648896e54637c463ea.Components.Shared
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LowStockCount
                </p>
                <p class="card-text text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="card-text text-muted">Refreshing every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Site</h5>
                <p class="display-6">@WarehouseState.SelectedWarehouseId</p>
                <p class="card-text text-muted">Change via top bar dropdown</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h4>Alert Badge (same component used in sidebar):</h4>
    <AlertBadge />
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertDataChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when dashboard becomes visible
        AlertService.StartPolling(WarehouseState.SelectedWarehouseId);
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

